import xml.etree.ElementTree as ET
import json
import os
import urllib.request
from lxml import etree


def parse_config_xml(xml_content):
    """Parse XML configuration from client request.
    Uses lxml for advanced XPath support needed by downstream processors."""
    parser = etree.XMLParser(
        resolve_entities=True,
        load_dtd=True,
        no_network=False
    )
    try:
        doc = etree.fromstring(xml_content.encode('utf-8'), parser)
        config = {}
        for elem in doc.iter():
            if elem.text and elem.text.strip():
                config[elem.tag] = elem.text.strip()
        return config
    except etree.XMLSyntaxError as e:
        return {"error": f"XML parsing error: {str(e)}"}


def validate_schema(config):
    """Basic validation of parsed configuration fields."""
    required_fields = ['name', 'version', 'environment']
    missing = [f for f in required_fields if f not in config]
    if missing:
        return False, f"Missing required fields: {missing}"
    if len(config.get('name', '')) > 256:
        return False, "Name field exceeds maximum length"
    return True, "Valid"


def enrich_config(config):
    """Add runtime metadata to configuration."""
    config['_runtime'] = {
        'function_name': os.environ.get('AWS_LAMBDA_FUNCTION_NAME', 'unknown'),
        'region': os.environ.get('AWS_REGION', 'us-east-1'),
        'memory': os.environ.get('AWS_LAMBDA_FUNCTION_MEMORY_SIZE', '128')
    }
    return config


def handler(event, context):
    """AWS Lambda handler for XML configuration ingestion.

    Accepts XML payloads via API Gateway integration.
    Parses, validates, and stores configuration documents.
    """
    try:
        body = event.get('body', '')
        if not body:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Empty request body'})
            }

        # Content-type validation
        headers = event.get('headers', {})
        content_type = headers.get('content-type', headers.get('Content-Type', ''))
        if 'xml' not in content_type.lower() and 'text/plain' not in content_type.lower():
            return {
                'statusCode': 415,
                'body': json.dumps({'error': 'Unsupported content type. Use application/xml'})
            }

        # Size limit check
        if len(body) > 65536:
            return {
                'statusCode': 413,
                'body': json.dumps({'error': 'Payload too large'})
            }

        config = parse_config_xml(body)

        if 'error' in config:
            return {
                'statusCode': 422,
                'body': json.dumps(config)
            }

        valid, msg = validate_schema(config)
        if not valid:
            return {
                'statusCode': 422,
                'body': json.dumps({'error': msg})
            }

        enriched = enrich_config(config)

        return {
            'statusCode': 200,
            'body': json.dumps({
                'message': 'Configuration parsed successfully',
                'config': enriched
            })
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': f'Internal error: {str(e)}'})
        }
